const item = items[0].json;

let name = item.name;
const path = item.parentReference.path;

// Replace "version" or "v" followed by optional space and number (e.g. V2, version 3) with "Revision {number}"
name = name.replace(/\b(version|v)\s*(\d+)?\b/gi, (_, _match, number) => {
  return number ? `Revision ${number}` : 'Revision';
});

// Extract the first number in the path after Projekte/
const mainNumberMatch = path.match(/\/EPCS Projekte\/(\d+)/);
const mainNumber = mainNumberMatch ? mainNumberMatch[1] : '00000';

// Extract the number directly after the word "Projekt" in the path
const projektNumberMatch = path.match(/Projekt\s*(\d+)/i);
let subProjectNumber = projektNumberMatch ? projektNumberMatch[1] : null;

// Prepend 0 if less than 10
if (subProjectNumber && parseInt(subProjectNumber) < 10) {
  subProjectNumber = '0' + parseInt(subProjectNumber);
}

// Default to "00" if no subproject number found
if (!subProjectNumber) {
  subProjectNumber = '00';
}

// Clean "-ready" from the name and trim
const cleanedName = name.replace(/-ready/i, '').trim();

// Combine into final markup name
const finalName = `${mainNumber}-${subProjectNumber} ${cleanedName}`;

return [
  {
    json: {
      originalName: item.name,
      markupName: finalName,
      projectId: mainNumber,
      subProjectId: subProjectNumber,
      originalPath: path
    }
  }
];

const item = items[0];

// Extract required fields
const { event, folder_name, path: rawPath } = item.json.body;

// Find the segment starting from "Projekte"
const match = rawPath.match(/EPCS Projekte.*$/i);
if (!match) {
  throw new Error("Could not extract the relevant path starting from 'Projekte'");
}

// Slice from "Projekte" onward
const relevantPath = match[0];

// Convert the extracted Windows-style path to Unix-style
const unixPath = relevantPath.replace(/\\/g, "/");
const fullRelativePath = `${unixPath}`;

// Encode each segment of the full path for the Graph API
const encodedPath = fullRelativePath
  .split("/")
  .map(encodeURIComponent)
  .join("/");

// Build the final Graph API-compatible path
const graphApiPath = `/sites/06bf948f-b86d-4e3a-861f-5d09c3c18034,79725fd7-bd81-426a-b070-2b1172d4b30f/drives/b!j5S_Bm24Ok6GH10Jw8GANNdfcnmBvWpCsHArEXLUsw-G4JEVDbY7SYGJqMTAGYGQ/root:/${encodedPath}`;

return [
  {
    json: {
      event,
      folder_name,
      graphApiPath
    }
  }
];

// Parse input JSON
const input = items[0].json;

// Extract values array
const values = input.value || [];

// Allowed MIME types
const allowedMimeTypes = [
  "image/jpeg",
  "image/png",
  "application/pdf"
];

// Filter files by allowed MIME types
const filtered = values.filter(v =>
  v.file && allowedMimeTypes.includes(v.file.mimeType)
);

// Return results as individual items (Loop Over Items compatible)
return filtered.map(v => ({ json: v }));

// Runs ONCE. Builds the project name/comment for the single create-project
// call. Reads the Graph metadata by reference (its direct input is now the
// binary items from "Download file"). Images themselves are uploaded later
// straight from the downloaded binary.
const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

let markupName = 'Untitled project';
let comment = '';
try {
  const d = $('Derive Markup name1').first().json;
  markupName = d.markupName || markupName;
  comment = d.projectId ?? '';
} catch (e) { /* keep defaults */ }

const images = $('Get download file meta data').all()
  .map(i => i.json)
  .filter(f => IMAGE_TYPES.includes(f.file?.mimeType));

if (images.length === 0) {
  throw new Error('No image files found in the folder (jpeg/png/webp/gif).');
}
if (images.length > 50) {
  throw new Error(`Too many images (${images.length}) \u2014 the API accepts at most 50 per project.`);
}

return [{ json: { name: markupName, comment, imageCount: images.length } }];

// Re-emits ONE item per downloaded image, each carrying its binary bytes
// (property 'data', straight from the SharePoint "Download file" node) plus
// the id of the project we just created. Because "Download file" is a direct
// ancestor of this node, n8n keeps its binary data available here.
//
// The next HTTP node auto-iterates over these items \u2014 one request per image,
// sequentially. That per-item iteration IS the loop; no splitInBatches needed.
const project = $('Create revision project').first().json.project;
if (!project?.id) {
  throw new Error('No project id in create-project response: ' + JSON.stringify($('Create revision project').first().json));
}

const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
const meta = $('Get download file meta data').all();
const files = $('Download file').all();

const out = [];
files.forEach((item, i) => {
  const mime = meta[i]?.json?.file?.mimeType;
  // Skip non-images (e.g. PDFs the meta node let through).
  if (mime && !IMAGE_TYPES.includes(mime)) return;
  out.push({
    json: {
      projectId: project.id,
      index: out.length + 1,
      name: item.binary?.data?.fileName || meta[i]?.json?.name || `image-${i + 1}`,
    },
    binary: item.binary,
  });
});

if (out.length === 0) {
  throw new Error('No image binaries to upload.');
}
return out;
